function downloadCSV(rows, fields, filename){
  const list=Array.isArray(rows)?rows:[];
  const cols=fields&&fields.length?fields:Object.keys(list[0]||{}).map(k=>[k,k]);
  const csv=[cols.map(c=>`"${String(c[1]).replaceAll('"','""')}"`).join(','),...list.map(r=>cols.map(c=>`"${String(r?.[c[0]]??'').replaceAll('"','""').replace(/\r?\n/g,' ')}"`).join(','))].join('\r\n');
  const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename.endsWith('.csv')?filename:filename+'.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function exportRegister(type,filtered){const key=type==='drawing'?'drawings':type==='wls'?'wls':'parts';const rows=cache[key]||[];const q=($('q')?.value||'').toLowerCase();const a=filtered?rows.filter(x=>matchesAdvanced(x,type)&&(!q||JSON.stringify(x).toLowerCase().includes(q))):rows;downloadCSV(a,filterFields(type),`Mutha_${type}_Register_${filtered?'Filtered':'All'}_${new Date().toISOString().slice(0,10)}.csv`)}
