const isDevelopmentAuditUser=()=>admin()||String(currentProfile?.department||'').toLowerCase()==='development';

const DEFAULT_PLANTS=['MFPL','MEPL-U3','MEPL-H21','MEPL-H25','DI','MSL'];
const DEFAULT_DEPARTMENTS=['Quality Assurance','Development','Production','Maintenance','Tool Room','Stores','Purchase','PPC','Engineering','Foundry','Machining','Dispatch / Logistics','HR / Admin','IT','Finance / Accounts','EHS / Safety','Sales / Marketing','Other'];
async function getRegistrationMasters(){let [p,d]=await Promise.all([sb.from('portal_plants').select('plant_name').eq('active',true).order('plant_name'),sb.from('portal_departments').select('department_name').eq('active',true).order('department_name')]);return {plants:(p.data||[]).map(x=>x.plant_name).length?(p.data||[]).map(x=>x.plant_name):DEFAULT_PLANTS,depts:(d.data||[]).map(x=>x.department_name).length?(d.data||[]).map(x=>x.department_name):DEFAULT_DEPARTMENTS}}
async function register(){let m=await getRegistrationMasters();document.getElementById("app").innerHTML=`<div class="auth"><div class="card auth-card"><div class="brand"><h1>USER REGISTRATION</h1><p>Enter correct employee, plant, department and contact details. Admin approval is required.</p></div><div id="rm"></div><form onsubmit="signup(event)"><div class="grid2"><div class="form-group"><label>Employee ID</label><input id="r_eid" required></div><div class="form-group"><label>Employee Name</label><input id="r_name" required></div><div class="form-group"><label>Department</label><select id="r_dept" required><option value="">Select Department</option>${m.depts.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="form-group"><label>Designation</label><input id="r_des" required></div><div class="form-group"><label>Plant / Unit</label><select id="r_plant" required><option value="">Select Plant / Unit</option>${m.plants.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="form-group"><label>Official Email</label><input id="r_email" type="email" required></div><div class="form-group"><label>WhatsApp / Mobile No.</label><input id="r_mobile" inputmode="numeric" pattern="[0-9+()\- ]{10,18}" placeholder="e.g. 919270717078" required></div><div class="form-group"><label>Reporting Manager</label><input id="r_manager" required></div><div class="form-group"><label><input id="r_wa" type="checkbox" checked> Receive WhatsApp updates</label></div><div class="form-group"><label><input id="r_em" type="checkbox" checked> Receive Email updates</label></div><div class="form-group"><label>Password</label><input id="r_pw" type="password" minlength="6" required></div><div class="form-group"><label>Confirm Password</label><input id="r_pw2" type="password" required></div></div><div class="actions"><button type="button" class="btn btn-secondary" onclick="login()">Back</button><button class="btn btn-primary">Register</button></div></form></div></div>`}
async function signup(e){e.preventDefault();if($("r_pw").value!==$("r_pw2").value)return err("rm","Passwords do not match");let mobile=$("r_mobile").value.trim();let digits=mobile.replace(/\D/g,'');if(digits.length<10||digits.length>15)return err('rm','Please enter a valid WhatsApp/mobile number.');let m={employee_id:$("r_eid").value.trim(),employee_name:$("r_name").value.trim(),department:$("r_dept").value,designation:$("r_des").value.trim(),plant_unit:$("r_plant").value,official_email:$("r_email").value.trim(),mobile_no:mobile,reporting_manager:$("r_manager").value.trim(),whatsapp_opt_in:$("r_wa").checked,email_opt_in:$("r_em").checked,requested_role:"Employee"};let r=await sb.auth.signUp({email:m.official_email,password:$("r_pw").value,data:m});if(r.error)return err("rm",r.error.message);document.getElementById("rm").innerHTML='<div class="alert alert-success">Registration submitted successfully. Admin will verify Plant, Department, role and module permissions before approval.</div>'}
function pending(){document.getElementById("app").innerHTML=`<div class="auth"><div class="card auth-card"><div class="brand"><h1>REGISTRATION PENDING</h1></div><div class="alert">Admin approval and module access assignment are pending.</div><button class="btn btn-primary" style="width:100%" onclick="logout()">Back to Login</button></div></div>`}
function render(){let n=`<button class="navbtn active" id="n_dashboard" onclick="go('dashboard')">📊 Dashboard</button>`;if(can("engineering_drawing","view"))n+=`<button class="navbtn" id="n_drawings" onclick="go('drawings')">📐 Engineering Drawing Register</button>`;if(can("wls","view"))n+=`<button class="navbtn" id="n_wls" onclick="go('wls')">🔦 WLS Report Register</button>`;if(can("master_part","view"))n+=`<button class="navbtn" id="n_parts" onclick="go('parts')">🧩 Plant-wise Master Part List</button>`;if(can("scanning_dwm","view"))n+=`<button class="navbtn" id="n_scanning" onclick="go('scanning')">📡 3D Scanning DWM & OEE</button>`;n+=`<button class="navbtn" id="n_requests" onclick="go('requests')">📄 Document Request</button>`;if(isDevelopmentAuditUser())n+=`<button class="navbtn" id="n_dev_audit" onclick="go('dev_audit')">📋 Development Internal Audit</button>`;n+=`<button class="navbtn" id="n_gantt" onclick="go('gantt')">📊 Gantt Chart</button><button class="navbtn" id="n_level3" onclick="go('level3')">📚 Level 3 Documents</button>`;if(admin())n+=`<button class="navbtn" id="n_users" onclick="go('users')">👥 User Access & Approvals</button><button class="navbtn" id="n_audit" onclick="go('audit')">🕘 Admin History & Audit Log</button>`;document.getElementById("app").innerHTML=`<div class="topbar"><div class="topbrand"><img src="assets/mutha-logo.png" alt="Mutha Group"><h2>MUTHA GROUP NPD PORTAL</h2></div><div class="top-user">${esc(currentProfile.employee_name)} | ${esc(currentProfile.role)} <button class="btn btn-secondary" onclick="logout()">Logout</button></div></div><div class="layout"><aside class="sidebar">${n}</aside><main class="main" id="main"></main></div><div class="developer-credit">Developed by <b>Mangesh Suresh Deshmukh</b> • Quality & Development</div>`;go(currentPage)}
async function logout(){await sb.auth.signOut();location.reload()}
async function go(p){const seq=++navSeq;currentPage=p;document.querySelectorAll(".navbtn").forEach(x=>x.classList.remove("active"));$("n_"+p)?.classList.add("active");const fn=({dashboard,drawings,wls,parts,scanning,requests,dev_audit,gantt,level3,users,audit}[p]||dashboard);try{await fn(seq)}catch(e){if(seq===navSeq&&$("main"))$("main").innerHTML=`<div class="alert alert-error">${esc(e.message||e)}</div>`}}
async function dashboard(seq=navSeq){
 const [dr,wr,pr,sr,recentR]=await Promise.all([
   can("engineering_drawing","view")?sb.from("engineering_drawing_register").select("status,plant_unit,customer_name,received_date"):Promise.resolve({data:[],count:null}),
   can("wls","view")?sb.from("wls_reports").select("unit_plant,status,customer_name,report_date"):Promise.resolve({data:[],count:null}),
   can("master_part","view")?sb.from("master_part_list").select("plant_unit,status,process,customer_name"):Promise.resolve({data:[],count:null}),
   can("scanning_dwm","view")?sb.from("scanning_tasks").select("plant_unit,work_status,priority,task_date"):Promise.resolve({data:[],count:null}),
   admin()?sb.from("portal_audit_log").select("created_at,module,action,record_label,actor_name").order("created_at",{ascending:false}).limit(8):Promise.resolve({data:[]})
 ]);
 if(seq!==navSeq)return;
 const drawings=dr.data||[],wlsRows=wr.data||[],parts=pr.data||[],scanRowsData=sr.data||[],recent=recentR.data||[];
 const countD=drawings.length,countW=wlsRows.length,countP=parts.length,countS=scanRowsData.length,total=countD+countW+countP+countS;
 const group=(rows,key)=>{const o={};rows.forEach(x=>{const v=String(x?.[key]||'Not specified').trim()||'Not specified';o[v]=(o[v]||0)+1});return Object.entries(o).sort((a,b)=>b[1]-a[1])};
 const plantW=group(wlsRows,'unit_plant').slice(0,8),plantP=group(parts,'plant_unit').slice(0,8),statusD=group(drawings,'status').slice(0,8),statusS=group(scanRowsData,'work_status').slice(0,8);
 const monthMap={};wlsRows.forEach(x=>{if(x.report_date){const d=String(x.report_date).slice(0,7);monthMap[d]=(monthMap[d]||0)+1}});const monthly=Object.entries(monthMap).sort((a,b)=>a[0].localeCompare(b[0])).slice(-8);
 const bars=(items)=>items.length?items.map(([k,v])=>`<div class="analysis-bar"><div class="analysis-label"><span>${esc(k)}</span><b>${v}</b></div><div class="analysis-track"><i style="width:${Math.max(4,Math.round(v/Math.max(1,items[0][1])*100))}%"></i></div></div>`).join(''):'<div class="empty">No data available.</div>';
 $('main').innerHTML=`<section class="npd-hero"><div class="npd-hero-overlay"></div><div class="npd-hero-copy"><div class="eyebrow">NEW PRODUCT DEVELOPMENT • QUALITY • DIGITAL TRANSFORMATION</div><div class="npd-title-row"><img src="assets/mutha-logo.png" class="npd-logo" alt="Mutha Group"><div><h1>MUTHA GROUP NPD PORTAL</h1><p>Engineering • Quality • Product Development • Digital Transformation</p></div></div></div><div class="npd-hero-images"><img src="assets/plant-building.png" alt="Mutha Group facility"><img src="assets/digital-transformation.png" alt="Digital transformation"></div></section>
 <div class="stats stylish-stats"><div class="stat"><div class="icon">📐</div><div class="n">${dr.count??countD}</div><div class="l">Engineering Drawings</div></div><div class="stat"><div class="icon">🔦</div><div class="n">${wr.count??countW}</div><div class="l">WLS Reports</div></div><div class="stat"><div class="icon">🧩</div><div class="n">${pr.count??countP}</div><div class="l">Master Parts</div></div><div class="stat"><div class="icon">📡</div><div class="n">${sr.count??countS}</div><div class="l">Scanning Tasks</div></div><div class="stat"><div class="icon">📊</div><div class="n">${total}</div><div class="l">Controlled Records</div></div><div class="stat"><div class="icon">🔐</div><div class="n">${admin()?"ADMIN":"USER"}</div><div class="l">Access Level</div></div></div>
 <div class="panel dashboard-analysis"><div class="page-title" style="margin-bottom:10px"><div><h2 style="margin:0">Portal Analysis</h2><p class="small">Live summary from the available portal records. Use module exports for detailed Excel/CSV analysis.</p></div><div class="actions-inline"><button class="btn btn-secondary" onclick="exportDashboardSummary()">⬇ Export Dashboard CSV</button></div></div>
 <div class="analysis-grid"><div class="analysis-card"><h3>WLS Reports by Plant</h3>${bars(plantW)}</div><div class="analysis-card"><h3>Master Parts by Plant</h3>${bars(plantP)}</div><div class="analysis-card"><h3>Drawing Status</h3>${bars(statusD)}</div><div class="analysis-card"><h3>Scanning Task Status</h3>${bars(statusS)}</div><div class="analysis-card wide"><h3>WLS Reports by Month</h3>${bars(monthly)}</div></div></div>
 <div class="panel"><div class="page-title" style="margin-bottom:8px"><div><h3 style="margin:0">Quick Export</h3><p class="small">CSV files open directly in Microsoft Excel.</p></div></div><div class="export-grid">${can("engineering_drawing","view")?`<button class="btn btn-secondary" onclick="exportRegister('drawing',false)">📐 Engineering Drawings CSV</button>`:''}${can("wls","view")?`<button class="btn btn-secondary" onclick="exportRegister('wls',false)">🔦 WLS Reports CSV</button>`:''}${can("master_part","view")?`<button class="btn btn-secondary" onclick="exportRegister('part',false)">🧩 Master Parts CSV</button>`:''}${can("scanning_dwm","view")?`<button class="btn btn-secondary" onclick="exportScanning(true)">📡 All Scanning Tasks CSV</button>`:''}</div></div>
 ${admin()?`<div class="panel"><div class="page-title" style="margin-bottom:8px"><div><h3 style="margin:0">Recent Updates</h3><p class="small">Latest portal changes visible to Admin.</p></div><button class="btn btn-secondary" onclick="go('audit')">View Complete History</button></div><div class="tablewrap"><table><thead><tr><th>Date & Time</th><th>Module</th><th>Action</th><th>Record</th><th>Updated By</th></tr></thead><tbody>${recent.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${esc(x.module)}</td><td>${esc(x.action)}</td><td>${esc(x.record_label||'-')}</td><td>${esc(x.actor_name||'-')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No recent updates.</td></tr>'}</tbody></table></div></div>`:''}`;
}
function exportDashboardSummary(){const rows=[['Engineering Drawings',document.querySelector('.stylish-stats .stat:nth-child(1) .n')?.textContent||'', 'WLS Reports',document.querySelector('.stylish-stats .stat:nth-child(2) .n')?.textContent||'', 'Master Parts',document.querySelector('.stylish-stats .stat:nth-child(3) .n')?.textContent||'', 'Scanning Tasks',document.querySelector('.stylish-stats .stat:nth-child(4) .n')?.textContent||'', 'Controlled Records',document.querySelector('.stylish-stats .stat:nth-child(5) .n')?.textContent||'']];downloadCSV(rows,[['0','Engineering Drawings'],['2','WLS Reports'],['4','Master Parts'],['6','Scanning Tasks'],['8','Controlled Records']],'Mutha_Dashboard_Summary.csv')}
