function listPage(type){const m=type==='drawing'?'engineering_drawing':type==='wls'?'wls':'master_part';if(!can(m,'view'))return $('main').innerHTML='<div class="alert alert-error">No access.</div>';const title=type==='drawing'?'Engineering Drawing Register':type==='wls'?'WLS Report Register':'Plant-wise Master Part List';const fs=type==='drawing'?DRAW:type==='wls'?WLS:PART;$('main').innerHTML=`<div class="page-title"><div><h1>${title}</h1><p>${can(m,'edit')?'Update enabled':'View only'} • ${fs.length} fields available</p></div><div class="actions-inline">${can(m,'add')?`<button class="btn btn-primary" onclick="portalForm('${type}')">＋ Add New Entry</button>`:''}<button class="btn btn-secondary" onclick="exportRegister('${type}',true)">⬇ Export Filtered CSV</button><button class="btn btn-secondary" onclick="exportRegister('${type}',false)">⬇ Export All CSV</button></div></div><div class="panel"><div class="searchbar advanced-searchbar"><input id="q" placeholder="Quick search across all fields..." oninput="refresh('${type}')"><button class="btn btn-secondary" onclick="openAdvancedFilter('${type}')">⚙ Advanced Filter</button><button class="btn btn-secondary" onclick="clearAdvancedFilter('${type}')">Clear Filters</button></div><div id="filter_summary" class="filter-summary"></div><div id="list">Loading...</div></div>`;refresh(type)}
function filterFields(type){return type==='drawing'?DRAW:type==='wls'?WLS:PART}
function filterInput(f,val){const key=f[0],label=f[1],v=val||'';if(/date/i.test(key))return `<div class="form-group"><label>${esc(label)} From</label><input type="date" id="af_${key}_from" value="${esc(v.from||'')}"><label class="sub-label">To</label><input type="date" id="af_${key}_to" value="${esc(v.to||'')}"></div>`;return `<div class="form-group"><label>${esc(label)}</label><input id="af_${key}" value="${esc(v)}" placeholder="Contains..."></div>`}
function openAdvancedFilter(type){const fs=filterFields(type),st=window._advFilters?.[type]||{};$('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal filter-modal"><div class="modal-header"><div><h2>Advanced Filter</h2><p class="small">${fs.length} fields • combine multiple conditions</p></div><button class="close" onclick="closeM()">×</button></div><div class="filter-grid">${fs.map(f=>filterInput(f,st[f[0]]||'')).join('')}</div><div class="actions"><button type="button" class="btn btn-secondary" onclick="clearAdvancedFilter('${type}',true)">Clear</button><button type="button" class="btn btn-secondary" onclick="closeM()">Cancel</button><button type="button" class="btn btn-primary" onclick="applyAdvancedFilter('${type}')">Apply Filter</button></div></div></div>`)}
function collectAdvancedFilter(type){const o={},fs=filterFields(type);fs.forEach(f=>{const k=f[0];if(/date/i.test(k)){const from=$('af_'+k+'_from')?.value||'',to=$('af_'+k+'_to')?.value||'';if(from||to)o[k]={from,to}}else{const v=$('af_'+k)?.value?.trim()||'';if(v)o[k]=v}});return o}
function applyAdvancedFilter(type){window._advFilters=window._advFilters||{};window._advFilters[type]=collectAdvancedFilter(type);closeM();refresh(type)}
function clearAdvancedFilter(type,inside=false){window._advFilters=window._advFilters||{};delete window._advFilters[type];if($('q'))$('q').value='';if(inside)closeM();refresh(type)}
function matchesAdvanced(x,type){const st=window._advFilters?.[type]||{},fs=filterFields(type);return fs.every(f=>{const k=f[0];if(!st[k])return true;if(typeof st[k]==='object'){const d=x[k]?String(x[k]).slice(0,10):'';return (!st[k].from||d>=st[k].from)&&(!st[k].to||d<=st[k].to)}return String(x[k]??'').toLowerCase().includes(String(st[k]).toLowerCase())})}
function filterSummary(type){const st=window._advFilters?.[type]||{},parts=[];Object.entries(st).forEach(([k,v])=>{const f=filterFields(type).find(x=>x[0]===k);if(f)parts.push(`${f[1]}: ${typeof v==='object'?(v.from||'')+' → '+(v.to||''):v}`)});return parts.length?`<b>Active filters:</b> ${parts.map(esc).join(' • ')}`:'<span class="small">No advanced filters applied.</span>'}
async function refresh(type){const table=type==='drawing'?'engineering_drawing_register':type==='wls'?'wls_reports':'master_part_list';let r=await sb.from(table).select('*').order('id',{ascending:false});if(r.error)return $('list').innerHTML=`<div class="alert alert-error">${esc(r.error.message)}</div>`;cache[type==='drawing'?'drawings':type==='wls'?'wls':'parts']=r.data||[];const q=($('q')?.value||'').toLowerCase(),a=(r.data||[]).filter(x=>matchesAdvanced(x,type)&&(!q||JSON.stringify(x).toLowerCase().includes(q))),fs=filterFields(type),visible=fs.slice(0,7);$('filter_summary').innerHTML=filterSummary(type)+` <span class="result-count">${a.length} result${a.length===1?'':'s'}</span>`;$('list').innerHTML=`<div class="tablewrap"><table><thead><tr>${visible.map(x=>`<th>${x[1]}</th>`).join('')}<th>Actions</th></tr></thead><tbody>${a.map(x=>`<tr>${visible.map(f=>`<td>${esc(x[f[0]])}</td>`).join('')}<td class="row-actions"><button class="btn btn-secondary" onclick="view('${type}',${x.id})">View</button>${can(type==='drawing'?'engineering_drawing':type==='wls'?'wls':'master_part','edit')?` <button class="btn btn-secondary" onclick="portalForm('${type}',${x.id})">Update</button>`:''}${admin()?` <button class="btn btn-danger" onclick="deleteRegister('${type}',${x.id})">Delete</button>`:''}</td></tr>`).join('')||`<tr><td colspan="${visible.length+1}" class="empty">No matching records found.</td></tr>`}</tbody></table></div>`}
function drawings(){listPage('drawing')}function wls(){listPage('wls')}function parts(){listPage('part')}
function historyLabel(type,row){const keys=type==='drawing'?['register_no','drawing_no','part_no','part_name']:type==='wls'?['report_no','wls_report_no','part_no','customer_name']:['part_no','part_name','customer_name','plant_unit'];const vals=keys.map(k=>row?.[k]).filter(v=>v!==null&&v!==undefined&&String(v).trim()!=='').map(v=>String(v).trim());return `${vals.slice(0,3).join(' • ')||'Previous Record'}${row?.id?` [ID ${row.id}]`:''}`}
function applyHistory(type,index){const rows=window._formHistoryRows||[];const row=rows[Number(index)];if(!row)return;const fs=type==='drawing'?DRAW:type==='wls'?WLS:PART;fs.forEach(f=>{const el=$('f_'+f[0]);if(el)el.value=row[f[0]]??''});const note=$('history_note');if(note)note.textContent='Previous record loaded. You can edit any field before saving as a new entry.'}
function uniqueFieldSuggestions(field,query=""){
 const rows=window._formHistoryRows||[]; const q=String(query??"").trim().toLowerCase(); const out=[]; const seen=new Set();
 for(const r of rows){ const v=r?.[field]; if(v===null||v===undefined) continue; const str=String(v).trim(); if(!str) continue;
   if(q && !str.toLowerCase().includes(q)) continue; if(!seen.has(str)){seen.add(str);out.push(str)}
 }
 return out;
}
function suggestionBoxId(type,field){return `suggestbox_${type}_${field}`}
function renderSmartSuggestions(type,field,value){
 const box=$(suggestionBoxId(type,field)); if(!box)return;
 const matches=uniqueFieldSuggestions(field,value); box.innerHTML='';
 if(!String(value??'').trim() || !matches.length){box.classList.remove('show');return;}
 matches.forEach(v=>{const b=document.createElement('button');b.type='button';b.className='suggestion-item';b.textContent=v;b.onclick=()=>{const inp=$("f_"+field);if(inp){inp.value=v;inp.dispatchEvent(new Event('input',{bubbles:true}));inp.focus();}box.classList.remove('show');};box.appendChild(b)});
 box.classList.add('show');
}
function refreshFieldSuggestions(type,field,value){renderSmartSuggestions(type,field,value)}
function chooseSmartSuggestion(field,value){const inp=$("f_"+field);if(inp){inp.value=value;inp.dispatchEvent(new Event('input',{bubbles:true}));inp.focus()}closeAllSuggestions()}
document.addEventListener('click',e=>{if(!e.target.closest('.smart-field'))closeAllSuggestions()});
function closeAllSuggestions(){document.querySelectorAll('.smart-suggestions.show').forEach(x=>x.classList.remove('show'))}
async function portalForm(type,id){const m=type==="drawing"?"engineering_drawing":type==="wls"?"wls":"master_part";if(!can(m,id?"edit":"add"))return alert("No permission.");const table=type==="drawing"?"engineering_drawing_register":type==="wls"?"wls_reports":"master_part_list",fs=type==="drawing"?DRAW:type==="wls"?WLS:PART;let x={};if(id){let r=await sb.from(table).select("*").eq("id",id).single();if(r.error)return alert(r.error.message);x=r.data}window._editSnapshot={type,id:id||0,data:{...x}};window._formHistoryRows=[];if(!id){let h=await sb.from(table).select("*").order("id",{ascending:false}).limit(5000);if(!h.error)window._formHistoryRows=h.data||[]}$('app').insertAdjacentHTML("beforeend",`<div class="modal-bg" id="modal"><div class="modal wide-modal"><div class="modal-header"><div><h2>${id?"Update Entry":"Add New Entry"}</h2><p class="small">${id?'Edit the required fields, then click Update Entry. Use Undo Changes to restore the original values.':'Enter data manually, or select a previous record. Each field also suggests previous values as you type.'}</p></div><button class="close" onclick="closeM()">×</button></div><div id="fm"></div>${!id?`<div class="history-copy-box"><div class="form-group"><label>Previous Record / History</label><select id="form_history" onchange="applyHistory('${type}',this.value)"><option value="">— Start with a blank new entry —</option>${window._formHistoryRows.map((r,i)=>`<option value="${i}">${esc(historyLabel(type,r))}</option>`).join('')}</select><div id="history_note" class="small">Select a previous record to copy all values. Every field remains editable.</div></div></div>`:''}<form onsubmit="save(event,'${type}',${id||0})"><div class="grid3">${fs.map(f=>{const vals=uniqueFieldSuggestions(f[0]);const initial=vals.length?vals.slice(0,30):[];return `<div class="form-group smart-field"><label>${f[1]}</label><div class="smart-input-wrap"><input id="f_${f[0]}" autocomplete="off" value="${esc(x[f[0]])}" onfocus="renderSmartSuggestions('${type}','${f[0]}',this.value)" oninput="refreshFieldSuggestions('${type}','${f[0]}',this.value)" onkeydown="if(event.key==='Escape'){closeAllSuggestions()}"/><div id="suggestbox_${type}_${f[0]}" class="smart-suggestions">${initial.map(v=>`<button type="button" class="suggestion-item" onclick="chooseSmartSuggestion('${f[0]}',${JSON.stringify(v).replace(/</g,'\u003c')})">${esc(v)}</button>`).join('')}</div></div><span class="field-hint">Type any text to see all matching previous values</span></div>`}).join("")}</div><div class="actions"><button type="button" class="btn btn-secondary" onclick="undoForm('${type}',${id||0})">↶ Undo Changes</button><button type="button" class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary">${id?'Update Entry':'＋ Add Entry'}</button></div></form></div></div>`)}
function undoForm(type,id){const snap=window._editSnapshot;if(!snap||snap.type!==type||Number(snap.id||0)!==Number(id||0))return;const fs=type==='drawing'?DRAW:type==='wls'?WLS:PART;fs.forEach(f=>{const el=$('f_'+f[0]);if(el)el.value=snap.data[f[0]]??''})}
async function save(e,type,id){e.preventDefault();const m=type==="drawing"?"engineering_drawing":type==="wls"?"wls":"master_part",table=type==="drawing"?"engineering_drawing_register":type==="wls"?"wls_reports":"master_part_list",fs=type==="drawing"?DRAW:type==="wls"?WLS:PART,o={};fs.forEach(f=>o[f[0]]=$("f_"+f[0]).value||null);if(type==="part"){o.updated_by=currentUser.id;if(!id)o.created_by=currentUser.id}let r=id?await sb.from(table).update(o).eq("id",id).select().single():await sb.from(table).insert(o).select().single();if(r.error)return err("fm",r.error.message);closeM();({drawing:drawings,wls:wls,part:parts}[type])()}
async function deleteRegister(type,id){if(!admin())return alert('Only Admin can delete records.');const label=type==='drawing'?'Engineering Drawing':type==='wls'?'WLS Report':'Master Part';const table=type==='drawing'?'engineering_drawing_register':type==='wls'?'wls_reports':'master_part_list';let r0=await sb.from(table).select('*').eq('id',id).single();if(r0.error)return alert(r0.error.message);const record=r0.data;const primary=type==='drawing'?(record.register_no||record.drawing_no||record.part_no):type==='wls'?(record.report_no||record.part_no):(`${record.part_no||''} ${record.part_name||''}`).trim();$('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal confirm-modal"><div class="modal-header"><div><h2>Confirm Delete</h2><p class="small">This action permanently deletes the selected ${esc(label)} entry.</p></div><button class="close" onclick="closeM()">×</button></div><div class="alert alert-error"><b>Delete:</b> ${esc(primary||('Record ID '+id))}<br><span class="small">Please confirm before continuing.</span></div><div class="actions"><button class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-danger" onclick="confirmDeleteRegister('${type}',${id})">Yes, Delete Entry</button></div></div></div>`)}
async function confirmDeleteRegister(type,id){const table=type==='drawing'?'engineering_drawing_register':type==='wls'?'wls_reports':'master_part_list';const r=await sb.from(table).delete().eq('id',id);if(r.error)return alert(r.error.message);closeM();({drawing:drawings,wls:wls,part:parts}[type])()}
async function view(type,id){
  const table=type==="drawing"?"engineering_drawing_register":type==="wls"?"wls_reports":"master_part_list";
  const fs=type==="drawing"?DRAW:type==="wls"?WLS:PART;
  const r=await sb.from(table).select("*").eq("id",id).single();
  if(r.error)return alert(r.error.message);
  const d=r.data||{};
  const groups=detailGroups(type,fs);
  const primary=type==="drawing"?(d.register_no||d.drawing_no||d.part_no||`Record #${id}`):type==="wls"?(d.report_no||d.part_no||`Report #${id}`):(d.part_no||d.part_name||`Part #${id}`);
  const subtitle=type==="drawing"?[d.customer_name,d.part_name].filter(Boolean).join(" • "):type==="wls"?[d.customer_name,d.short_name,d.part_no].filter(Boolean).join(" • "):[d.customer_name,d.part_name,d.plant_unit].filter(Boolean).join(" • ");
  $("app").insertAdjacentHTML("beforeend",`<div class="modal-bg" id="modal"><div class="modal detail-modal"><div class="detail-hero"><div><div class="detail-kicker">${esc(type==="drawing"?"ENGINEERING DRAWING":type==="wls"?"WLS REPORT":"MASTER PART")}</div><h2>${esc(primary)}</h2><p>${esc(subtitle||"Complete record details")}</p></div><button class="close detail-close" onclick="closeM()">×</button></div><div class="detail-toolbar"><span class="detail-badge">${fs.length} fields</span><span class="detail-help">Read-only view • all available fields shown</span></div>${groups.map(g=>`<section class="detail-section"><div class="detail-section-head"><h3>${esc(g.title)}</h3><span>${g.fields.length} fields</span></div><div class="detail-grid">${g.fields.map(f=>`<div class="detail-item"><div class="detail-label">${esc(f[1])}</div><div class="detail-value ${!d[f[0]]?'muted':''}">${esc(d[f[0]]??"Not provided")}</div></div>`).join("")}</div></section>`).join("")}<div class="actions detail-actions"><button class="btn btn-secondary" onclick="closeM()">Close</button>${can(type==="drawing"?"engineering_drawing":type==="wls"?"wls":"master_part","edit")?`<button class="btn btn-primary" onclick="closeM();portalForm('${type}',${id})">✏ Update Entry</button>`:""}${admin()?`<button class="btn btn-danger" onclick="closeM();deleteRegister('${type}',${id})">🗑 Delete</button>`:""}</div></div></div>`)
}
function detailGroups(type,fs){
  const keys=(...names)=>fs.filter(f=>names.includes(f[0]));
  if(type==="drawing")return[
    {title:"Document Identification",fields:keys("register_no","received_from","drawing_type","received_date","received_purpose","customer_name","part_name","part_no","drawing_no","rev_no","rev_date")},
    {title:"Issue & Distribution Control",fields:keys("department_issued_to","issue_type","copy_type","copy_no","issue_date","issue_purpose","return_withdrawal_date","status")},
    {title:"Change, Location & Backup",fields:keys("change_details","hard_copy_location","soft_copy_location","backup_date","backup_media")},
    {title:"Review & Approval",fields:keys("revision_review_date","prepared_by","reviewed_by","approved_by","remarks")}
  ];
  if(type==="wls")return[
    {title:"Report Identification",fields:keys("sr_no","report_no","customer_name","unit_plant","short_name","part_no","part_type","cavity_no")},
    {title:"Inspection & Drawing Control",fields:keys("tolerance_standard","drawing_revision","report_type","report_revision","alignment","report_date","stage_purpose")},
    {title:"Result & Approval",fields:keys("conclusion","abnormality","remarks","prepared_by","reviewed_by","approved_by")}
  ];
  return[
    {title:"Part Identification",fields:keys("index","plant_unit","customer_name","part_no","part_name","drawing_no","revision","part_type","model","status","remarks")},
    {title:"Material & Process",fields:keys("material","process","short_name","drawing_revision","customer_vendor","moulding_process","material_grade","frequency","active_status")},
    {title:"Planning & Dispatch",fields:keys("total_plan_qty","low_plan","medium_plan","high_plan","plan_months","dispatch_type")},
    {title:"Pattern & Core Details",fields:keys("core_availability","pattern_cavities","plan_qty_cast","core_boxes","main_core_cavities","side_core_cavities")}
  ];
}

function renderUsers(){let q=($('user_q')?.value||'').toLowerCase(),d=$('user_dept')?.value||'',p=$('user_plant')?.value||'';let a=(window._portalUsers||[]).filter(u=>(!d||u.department===d)&&(!p||u.plant_unit===p)&&(!q||JSON.stringify(u).toLowerCase().includes(q)));$('user_rows').innerHTML=a.map(u=>`<tr><td><b>${esc(u.employee_name)}</b><br><small>ID: ${esc(u.employee_id||'-')}<br>${esc(u.official_email||'-')}<br>WA: ${esc(u.mobile_no||'-')}</small></td><td><select id="plant_${u.id}">${(window._userPlants||DEFAULT_PLANTS).map(x=>`<option ${u.plant_unit===x?'selected':''}>${esc(x)}</option>`).join('')}</select></td><td><select id="dept_${u.id}">${(window._userDepts||DEFAULT_DEPARTMENTS).map(x=>`<option ${u.department===x?'selected':''}>${esc(x)}</option>`).join('')}</select></td><td><select id="role_${u.id}">${['Employee','Manager','QA','Development','Viewer','Admin'].map(x=>`<option ${u.role===x?'selected':''}>${x}</option>`).join('')}</select></td><td><select id="st_${u.id}">${['Pending','Approved','Rejected'].map(x=>`<option ${u.approval_status===x?'selected':''}>${x}</option>`).join('')}</select></td><td><label><input id="wa_${u.id}" type="checkbox" ${u.whatsapp_opt_in!==false?'checked':''}> WhatsApp</label><br><label><input id="em_${u.id}" type="checkbox" ${u.email_opt_in!==false?'checked':''}> Email</label></td><td>${['engineering_drawing','wls','master_part','scanning_dwm'].map(m=>`<div><b>${m}</b> <label><input id="${u.id}_${m}_view" type="checkbox" ${u._perms[m]?.can_view?'checked':''}>V</label> <label><input id="${u.id}_${m}_add" type="checkbox" ${u._perms[m]?.can_add?'checked':''}>A</label> <label><input id="${u.id}_${m}_edit" type="checkbox" ${u._perms[m]?.can_edit?'checked':''}>E</label></div>`).join('')}</td><td><button class="btn btn-primary" onclick="saveAccess('${u.id}')">Save</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No users found.</td></tr>'}
async function users(seq=navSeq){
  if(!admin()){ return $('main').innerHTML='<div class="alert alert-error">Admin access required.</div>'; }
  $('main').innerHTML='<div class="panel"><div class="small">Loading User Access & Approvals...</div></div>';
  const [u,p,m]=await Promise.all([
    sb.from('user_profiles').select('*').order('employee_name'),
    sb.from('user_module_permissions').select('*'),
    getRegistrationMasters()
  ]);
  if(seq!==navSeq)return;
   if(u.error)return $('main').innerHTML=`<div class="alert alert-error">${esc(u.error.message)}</div>`;
  if(p.error)return $('main').innerHTML=`<div class="alert alert-error">${esc(p.error.message)}</div>`;
  window._userPlants=m.plants; window._userDepts=m.depts;
  const perms={}; (p.data||[]).forEach(x=>{perms[x.user_id]??={}; perms[x.user_id][x.module]=x});
  window._portalUsers=(u.data||[]).map(x=>({...x,_perms:perms[x.id]||{}}));
  $('main').innerHTML=`<div class="page-title"><div><h1>User Access & Approvals</h1><p>Admin control for user approval, role, plant, department, notifications and module permissions.</p></div><div class="actions-inline"><button class="btn btn-secondary" onclick="exportUsers()">⬇ Export Users CSV</button></div></div>
  <div class="panel"><div class="searchbar advanced-searchbar"><input id="user_q" placeholder="Search employee, ID or email..." oninput="userFilters()"><select id="user_dept" onchange="userFilters()"><option value="">All Departments</option>${m.depts.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="user_plant" onchange="userFilters()"><option value="">All Plants</option>${m.plants.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></div>
  <div class="panel"><div class="tablewrap"><table><thead><tr><th>Employee</th><th>Plant</th><th>Department</th><th>Role</th><th>Approval</th><th>Notifications</th><th>Module Access<br><span class="small">V=View A=Add E=Edit</span></th><th>Action</th></tr></thead><tbody id="user_rows"></tbody></table></div></div>`;
  renderUsers();
}
function exportUsers(){const rows=window._portalUsers||[];downloadCSV(rows,[['employee_id','Employee ID'],['employee_name','Employee Name'],['department','Department'],['designation','Designation'],['plant_unit','Plant'],['official_email','Email'],['mobile_no','Mobile'],['reporting_manager','Reporting Manager'],['role','Role'],['approval_status','Approval Status'],['whatsapp_opt_in','WhatsApp Opt-in'],['email_opt_in','Email Opt-in']],`Mutha_Portal_Users_${new Date().toISOString().slice(0,10)}.csv`)}
function userFilters(){renderUsers()}
async function saveAccess(id){let r=await sb.from("user_profiles").update({plant_unit:$(`plant_${id}`).value,department:$(`dept_${id}`).value,role:$(`role_${id}`).value,approval_status:$(`st_${id}`).value,whatsapp_opt_in:$(`wa_${id}`).checked,email_opt_in:$(`em_${id}`).checked}).eq("id",id);if(r.error)return alert(r.error.message);for(const m of ["engineering_drawing","wls","master_part","scanning_dwm"]){let x=await sb.from("user_module_permissions").upsert({user_id:id,module:m,can_view:$(`${id}_${m}_view`).checked,can_add:$(`${id}_${m}_add`).checked,can_edit:$(`${id}_${m}_edit`).checked},{onConflict:"user_id,module"});if(x.error)return alert(x.error.message)}alert("User profile and access saved. History and notification queue updated.");users()}

async function requests(seq=navSeq){
 const r=await sb.from('portal_document_requests').select('*').order('created_at',{ascending:false}).limit(admin()?300:100);
 if(r.error){$('main').innerHTML=`<div class="alert alert-error">${esc(r.error.message)}<br><span class="small">If the Document Request table has not been created, run PORTAL_DOCUMENT_REQUESTS.sql in Supabase SQL Editor.</span></div>`;return}
 const rows=(r.data||[]);window._requestRows=rows;
 $('main').innerHTML=`<div class="page-title"><div><h1>Document Request</h1><p>Request an Engineering Drawing, WLS Report or other controlled document and specify delivery by Teams or Email.</p></div><button class="btn btn-primary" onclick="requestForm()">＋ New Request</button><button class="btn btn-secondary" onclick="exportRequests()">⬇ Export CSV</button></div>
 <div class="panel request-intro"><div class="request-cards"><div><b>📐 Engineering Drawing</b><span>Request by drawing/register number.</span></div><div><b>🔦 WLS Report</b><span>Request by WLS report number.</span></div><div><b>📧 Delivery</b><span>Select Teams or Email.</span></div></div></div>
 <div class="panel"><div class="page-title" style="margin-bottom:10px"><div><h3 style="margin:0">${admin()?'All Document Requests':'My Document Requests'}</h3><p class="small">${admin()?'Admin can review, update status and delete requests.':'Your submitted requests and their current status.'}</p></div></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Request Type</th><th>Reference</th><th>Purpose</th><th>Delivery</th><th>Requested By</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${esc(x.request_type)}</td><td>${esc(x.wls_report_no||x.drawing_no||x.part_no||'-')}</td><td>${esc(x.purpose||'-')}</td><td>${esc(x.delivery_method)}<br><span class="small">${esc(x.delivery_to||'-')}</span></td><td>${esc(x.requester_name||'-')}</td><td><span class="badge ${x.status==='Completed'?'active':x.status==='Rejected'?'obsolete':'review'}">${esc(x.status)}</span></td><td>${admin()?`<button class="btn btn-secondary" onclick="updateRequest(${x.id})">Update</button> <button class="btn btn-danger" onclick="deleteRequest(${x.id})">Delete</button>`:`<button class="btn btn-secondary" onclick="viewRequest(${x.id})">View</button>`}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No document requests yet.</td></tr>'}</tbody></table></div></div>`
}
function exportRequests(){downloadCSV(window._requestRows||[],[['created_at','Date'],['request_type','Request Type'],['wls_report_no','WLS Report No.'],['drawing_no','Drawing / Register No.'],['part_no','Part No.'],['document_name','Document'],['purpose','Purpose'],['delivery_method','Delivery Method'],['delivery_to','Delivery To'],['requester_name','Requested By'],['status','Status'],['admin_remarks','Admin Remarks']],`Mutha_Document_Requests_${new Date().toISOString().slice(0,10)}.csv`)}
function requestForm(id){
 if(id && !admin())return alert('Only Admin can update a request.');
 const x=(window._requestRows||[]).find(a=>a.id===id)||{};
 $('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal wide-modal"><div class="modal-header"><div><h2>${id?'Update Document Request':'New Document Request'}</h2><p class="small">Enter the document reference and where you want the file delivered.</p></div><button class="close" onclick="closeM()">×</button></div><form onsubmit="saveRequest(event,${id||0})"><div class="grid2"><div class="form-group"><label>Request Type</label><select id="rq_type" required><option>WLS Report</option><option>Engineering Drawing</option><option>Master Part Information</option><option>Other Controlled Document</option></select></div><div class="form-group"><label>WLS Report No.</label><input id="rq_wls" value="${esc(x.wls_report_no||'')}" placeholder="e.g. MG-2026-WLS-00001"></div><div class="form-group"><label>Drawing / Register No.</label><input id="rq_draw" value="${esc(x.drawing_no||'')}" placeholder="Drawing or register number"></div><div class="form-group"><label>Part No.</label><input id="rq_part" value="${esc(x.part_no||'')}" placeholder="Part number"></div><div class="form-group full"><label>Document / File Required</label><input id="rq_doc" value="${esc(x.document_name||'')}" placeholder="e.g. PDF report, latest drawing revision, CAD/PDF"></div><div class="form-group full"><label>Purpose / Requirement</label><textarea id="rq_purpose" required placeholder="Why do you require this document?"></textarea></div><div class="form-group"><label>Delivery Method</label><select id="rq_method" onchange="toggleRequestDelivery()"><option>Microsoft Teams</option><option>Email</option></select></div><div class="form-group"><label>Teams / Email Address</label><input id="rq_to" value="${esc(x.delivery_to||currentProfile?.official_email||'')}" required placeholder="Teams user/channel or email address"></div>${admin()?`<div class="form-group"><label>Status</label><select id="rq_status"><option>Pending</option><option>In Progress</option><option>Completed</option><option>Rejected</option></select></div><div class="form-group"><label>Admin Remarks</label><textarea id="rq_remarks" placeholder="Action / file location / remarks"></textarea></div>`:''}</div><div class="actions"><button type="button" class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary">${id?'Update Request':'Submit Request'}</button></div></form></div></div>`);
 if(id){$('rq_type').value=x.request_type||'WLS Report';$('rq_purpose').value=x.purpose||'';$('rq_status').value=x.status||'Pending';$('rq_remarks').value=x.admin_remarks||''}
}
async function saveRequest(e,id){e.preventDefault();const payload={request_type:$('rq_type').value,wls_report_no:$('rq_wls').value.trim()||null,drawing_no:$('rq_draw').value.trim()||null,part_no:$('rq_part').value.trim()||null,document_name:$('rq_doc').value.trim()||null,purpose:$('rq_purpose').value.trim(),delivery_method:$('rq_method').value,delivery_to:$('rq_to').value.trim(),status:admin()&&id?$('rq_status').value:'Pending',admin_remarks:admin()&&id?$('rq_remarks').value.trim()||null:null};let r;if(id)r=await sb.from('portal_document_requests').update(payload).eq('id',id);else{payload.requester_id=currentUser.id;payload.requester_name=currentProfile.employee_name;payload.requester_email=currentProfile.official_email;r=await sb.from('portal_document_requests').insert(payload)}if(r.error)return alert(r.error.message);closeM();requests()}
async function updateRequest(id){let r=await sb.from('portal_document_requests').select('*').eq('id',id).single();if(r.error)return alert(r.error.message);window._requestRows=[r.data];requestForm(id)}
async function viewRequest(id){let r=await sb.from('portal_document_requests').select('*').eq('id',id).single();if(r.error)return alert(r.error.message);let x=r.data;$('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal detail-modal"><div class="detail-hero"><div><div class="detail-kicker">DOCUMENT REQUEST</div><h2>${esc(x.request_type)}</h2><p>${esc(x.wls_report_no||x.drawing_no||x.part_no||'Request')}</p></div><button class="close" onclick="closeM()">×</button></div><div class="detail-section"><div class="detail-grid">${[['Request Type',x.request_type],['WLS Report No.',x.wls_report_no],['Drawing / Register No.',x.drawing_no],['Part No.',x.part_no],['Document',x.document_name],['Purpose',x.purpose],['Delivery Method',x.delivery_method],['Delivery To',x.delivery_to],['Status',x.status],['Admin Remarks',x.admin_remarks],['Requested By',x.requester_name],['Requested On',x.created_at?new Date(x.created_at).toLocaleString():'-']].map(a=>`<div class="detail-item"><div class="detail-label">${esc(a[0])}</div><div class="detail-value ${!a[1]?'muted':''}">${esc(a[1]||'Not provided')}</div></div>`).join('')}</div></div><div class="detail-actions"><button class="btn btn-secondary" onclick="closeM()">Close</button></div></div></div>`)}
async function deleteRequest(id){if(!admin())return; if(!confirm('Delete this document request? This action cannot be undone.'))return;let r=await sb.from('portal_document_requests').delete().eq('id',id);if(r.error)return alert(r.error.message);requests()}
function toggleRequestDelivery(){}

function devAuditStatusClass(v){
  const x=String(v||'Pending').toLowerCase();
  if(x==='conforming')return 'active';
  if(x==='nc'||x==='major nc'||x==='minor nc')return 'obsolete';
  if(x==='ofi')return 'review';
  return 'pending';
}
function renderDevelopmentAudit(){
  if(!isDevelopmentAuditUser())return $('main').innerHTML='<div class="alert alert-error">Development Department access required.</div>';
  const data=DEVELOPMENT_AUDIT_DATA;
  const saved=JSON.parse(localStorage.getItem('mutha_dev_audit_draft')||'{}');
  const statuses=saved.statuses||{};
  const remarks=saved.remarks||{};
  const sections=[...new Set(data.checklist.map(x=>x.section))];
  const hist=data.history||[];
  $('main').innerHTML=`<div class="page-title"><div><h1>Development Department Internal Audit</h1><p>Internal Department Audit Checklist – Development & Pattern Shop • ISO 9001:2015 / IATF 16949:2016</p></div><div class="actions-inline"><button class="btn btn-secondary" onclick="devAuditExport()">Export CSV</button><button class="btn btn-secondary" onclick="devAuditReset()">Reset Draft</button><button class="btn btn-primary" onclick="devAuditSave()">Save Draft</button></div></div>
  <div class="panel audit-meta-panel"><div class="audit-meta-grid">
    <div class="form-group"><label>Format No.</label><input value="MF-L-DEVP-17" readonly></div>
    <div class="form-group"><label>Revision No.</label><input value="00" readonly></div>
    <div class="form-group"><label>Revision Date</label><input value="07-Jul-2026" readonly></div>
    <div class="form-group"><label>Department</label><input value="Development & Pattern Shop" readonly></div>
    <div class="form-group"><label>Audit No.</label><input id="dev_audit_no" value="${esc(saved.audit_no||'IA/DEVP/2026/03')}"></div>
    <div class="form-group"><label>Audit Plan Date</label><input id="dev_plan_date" type="date" value="${esc(saved.plan_date||'')}"></div>
    <div class="form-group"><label>Audit Actual Date</label><input id="dev_actual_date" type="date" value="${esc(saved.actual_date||'')}"></div>
    <div class="form-group"><label>Lead Auditor</label><input id="dev_auditor" value="${esc(saved.auditor||currentProfile?.employee_name||'')}"></div>
  </div></div>
  <div class="audit-kpis" id="dev_audit_kpis"></div>
  <div class="panel"><div class="page-title audit-history-title"><div><h3>Previous Audit History</h3><p class="small">Imported from the Development Department audit workbook.</p></div></div>
  <div class="tablewrap audit-history-wrap"><table><thead><tr><th>Audit No.</th><th>Plan Date</th><th>Actual Date</th><th>Total</th><th>Conforming</th><th>NC</th><th>OFI</th><th>Major NC</th><th>Minor NC</th></tr></thead><tbody>${hist.map(x=>`<tr><td>${esc(x.audit_no)}</td><td>${x.plan_date?new Date(x.plan_date).toLocaleDateString():'-'}</td><td>${x.actual_date?new Date(x.actual_date).toLocaleDateString():'-'}</td><td>${esc(x.total??'-')}</td><td>${esc(x.conforming??'-')}</td><td>${esc(x.nc??'-')}</td><td>${esc(x.ofi??'-')}</td><td>${esc(x.major_nc??'-')}</td><td>${esc(x.minor_nc??'-')}</td></tr>`).join('')}</tbody></table></div></div>
  <div class="panel"><div class="audit-filterbar"><input id="dev_audit_q" placeholder="Search checkpoint, clause, evidence..." oninput="renderDevAuditRows()"><select id="dev_audit_section" onchange="renderDevAuditRows()"><option value="">All Sections</option>${sections.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="dev_audit_result" onchange="renderDevAuditRows()"><option value="">All Results</option><option>Pending</option><option>Conforming</option><option>NC</option><option>OFI</option><option>Major NC</option><option>Minor NC</option></select></div>
  <div class="tablewrap dev-audit-tablewrap"><table><thead><tr><th>#</th><th>Section</th><th>Audit Check Point</th><th>ISO / IATF Clause</th><th>Auditor – What to Check?</th><th>How to Check?</th><th>Evidence / Record</th><th>Result</th><th>Remarks / NC Details</th><th>Responsibility</th><th>Target</th><th>Closure</th></tr></thead><tbody id="dev_audit_rows"></tbody></table></div></div>`;
  renderDevAuditRows();
}
function renderDevAuditRows(){
  const q=String($('dev_audit_q')?.value||'').toLowerCase();
  const sec=$('dev_audit_section')?.value||'';
  const rf=$('dev_audit_result')?.value||'';
  const saved=JSON.parse(localStorage.getItem('mutha_dev_audit_draft')||'{}');
  const statuses=saved.statuses||{}, remarks=saved.remarks||{};
  const rows=DEVELOPMENT_AUDIT_DATA.checklist.filter(x=>(!sec||x.section===sec)&&(!rf||(statuses[x.no]||'Pending')===rf)&&(!q||[x.section,x.checkpoint,x.clause,x.what,x.method,x.evidence].join(' ').toLowerCase().includes(q)));
  $('dev_audit_rows').innerHTML=rows.map(x=>{const st=statuses[x.no]||'Pending';return `<tr><td>${x.no}</td><td>${esc(x.section)}</td><td>${esc(x.checkpoint)}</td><td>${esc(x.clause)}</td><td>${esc(x.what)}</td><td>${esc(x.method)}</td><td>${esc(x.evidence)}</td><td><select class="audit-result-select badge ${devAuditStatusClass(st)}" data-audit-no="${x.no}" onchange="devAuditChange(${x.no},this.value)"><option ${st==='Pending'?'selected':''}>Pending</option><option ${st==='Conforming'?'selected':''}>Conforming</option><option ${st==='NC'?'selected':''}>NC</option><option ${st==='OFI'?'selected':''}>OFI</option><option ${st==='Major NC'?'selected':''}>Major NC</option><option ${st==='Minor NC'?'selected':''}>Minor NC</option></select></td><td><input class="audit-remark-input" value="${esc(remarks[x.no]||'')}" placeholder="Enter remarks / evidence" onchange="devAuditRemark(${x.no},this.value)"></td><td><input class="audit-small-input" value="${esc(saved.responsibility?.[x.no]||x.responsibility||'')}" onchange="devAuditResp(${x.no},this.value)"></td><td>${esc(x.target||'-')}</td><td><input class="audit-small-input" value="${esc(saved.closure?.[x.no]||x.closure||'')}" onchange="devAuditClosure(${x.no},this.value)"></td></tr>`}).join('')||'<tr><td colspan="12" class="empty">No matching checkpoints.</td></tr>';
  updateDevAuditKpis();
}
function devAuditState(){
  return JSON.parse(localStorage.getItem('mutha_dev_audit_draft')||'{}');
}
function saveDevAuditState(s){localStorage.setItem('mutha_dev_audit_draft',JSON.stringify(s));}
function devAuditChange(no,val){const s=devAuditState();s.statuses=s.statuses||{};s.statuses[no]=val;saveDevAuditState(s);updateDevAuditKpis();}
function devAuditRemark(no,val){const s=devAuditState();s.remarks=s.remarks||{};s.remarks[no]=val;saveDevAuditState(s);}
function devAuditResp(no,val){const s=devAuditState();s.responsibility=s.responsibility||{};s.responsibility[no]=val;saveDevAuditState(s);}
function devAuditClosure(no,val){const s=devAuditState();s.closure=s.closure||{};s.closure[no]=val;saveDevAuditState(s);}
function updateDevAuditKpis(){
  const s=devAuditState(), st=s.statuses||{}, vals=DEVELOPMENT_AUDIT_DATA.checklist.map(x=>st[x.no]||'Pending');
  const counts={Pending:0,Conforming:0,NC:0,OFI:0,'Major NC':0,'Minor NC':0};vals.forEach(v=>counts[v]=(counts[v]||0)+1);
  const k=$('dev_audit_kpis'); if(!k)return;
  k.innerHTML=`<div><b>${vals.length}</b><span>Total Checkpoints</span></div><div class="good"><b>${counts.Conforming}</b><span>Conforming</span></div><div class="bad"><b>${counts.NC+counts['Major NC']+counts['Minor NC']}</b><span>NC</span></div><div class="ofi"><b>${counts.OFI}</b><span>OFI</span></div><div class="pending"><b>${counts.Pending}</b><span>Pending</span></div>`;
}
function devAuditSave(){
  const s=devAuditState();
  s.audit_no=$('dev_audit_no')?.value||'';s.plan_date=$('dev_plan_date')?.value||'';s.actual_date=$('dev_actual_date')?.value||'';s.auditor=$('dev_auditor')?.value||'';
  saveDevAuditState(s);alert('Development Internal Audit draft saved on this browser.');
}
function devAuditReset(){if(!confirm('Reset the Development Internal Audit draft on this browser?'))return;localStorage.removeItem('mutha_dev_audit_draft');renderDevelopmentAudit();}
function devAuditExport(){
  const s=devAuditState(), rows=DEVELOPMENT_AUDIT_DATA.checklist.map(x=>({No:x.no,Section:x.section,Checkpoint:x.checkpoint,Clause:x.clause,What_to_Check:x.what,Method:x.method,Evidence:x.evidence,Result:s.statuses?.[x.no]||'Pending',Remarks:s.remarks?.[x.no]||'',Responsibility:s.responsibility?.[x.no]||x.responsibility||'',Target:x.target||'',Closure:s.closure?.[x.no]||x.closure||''}));
  const head=Object.keys(rows[0]);const csv=[head.join(','),...rows.map(r=>head.map(k=>`"${String(r[k]??'').replaceAll('"','""')}"`).join(','))].join('\n');
  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`Development_Internal_Audit_${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}
async function dev_audit(seq=navSeq){renderDevelopmentAudit();}



function renderGantt(){
  const g=DEVELOPMENT_GANTT;
  $('main').innerHTML=`<div class="page-title"><div><h1>📊 Development Gantt Chart</h1><p>${esc(g.title)} • ${esc(g.period)}</p></div><div class="actions-inline"><a class="btn btn-secondary" href="documents/Mutha_Development_Gantt_Schedule.xlsx" download>⬇ Download Excel</a><button class="btn btn-secondary" onclick="exportGantt()">⬇ Export CSV</button></div></div>
  <div class="panel gantt-summary"><div class="request-cards"><div><b>${g.activities.length}</b><span>Activities</span></div><div><b>${g.weeks.length}</b><span>Timeline Weeks</span></div><div><b>PLAN / ACTUAL</b><span>Schedule tracking</span></div></div></div>
  <div class="panel">
    <div class="gantt-toolbar">
      <input id="gantt_q" placeholder="Search activity..." oninput="renderGanttRows()">
      <button class="btn btn-secondary" onclick="$('gantt_q').value='';renderGanttRows()">Clear</button>
      <span class="gantt-legend"><span class="legend-plan">PLAN</span><span class="legend-actual">ACTUAL</span></span>
    </div>
    <div class="gantt-wrap gantt-excel-wrap">
      <table class="gantt-table gantt-excel-table">
        <thead>
          <tr>
            <th rowspan="2" class="gantt-no">No.</th>
            <th rowspan="2" class="gantt-activity">Activity planned</th>
            <th rowspan="2" class="gantt-type">Type</th>
            ${g.weeks.map((w,i)=>`<th><div>${esc(g.months[i]||'')}</div><b>${esc(w)}</b></th>`).join('')}
          </tr>
          <tr class="gantt-subhead">${g.weeks.map(()=>'<th>Week</th>').join('')}</tr>
        </thead>
        <tbody id="gantt_rows"></tbody>
      </table>
    </div>
    <div class="small gantt-note">Layout follows the supplied Development Schedule Gantt format. Each activity has a PLAN row and an ACTUAL row; current source data contains planned weeks only.</div>
  </div>`;
  renderGanttRows();
}
function exportGantt(){const rows=DEVELOPMENT_GANTT.activities.map(x=>({No:x.no,Activity:x.activity,Type:'PLAN',Planned_Weeks:(x.weeks||[]).map((v,i)=>v==='Plan'?DEVELOPMENT_GANTT.weeks[i]:'').filter(Boolean).join(' | ')}));downloadCSV(rows,null,`Mutha_Development_Gantt_${new Date().toISOString().slice(0,10)}.csv`)}
function renderGanttRows(){
  const q=String($('gantt_q')?.value||'').toLowerCase();
  const rows=DEVELOPMENT_GANTT.activities.filter(x=>!q||String(x.activity).toLowerCase().includes(q));
  $('gantt_rows').innerHTML=rows.map(x=>{
    const plan=x.weeks||[];
    return `<tr class="gantt-plan-row"><td rowspan="2">${esc(x.no)}</td><td rowspan="2" class="gantt-activity-cell"><b>${esc(x.activity)}</b></td><td class="gantt-type-cell"><b>P</b></td>${plan.map(v=>`<td class="${v==='Plan'?'gantt-plan':''}">${v==='Plan'?'<span>PLAN</span>':''}</td>`).join('')}</tr>
    <tr class="gantt-actual-row"><td class="gantt-type-cell"><b>A</b></td>${plan.map(()=>`<td class="gantt-actual-cell"></td>`).join('')}</tr>`;
  }).join('')||'<tr><td colspan="13" class="empty">No matching activities.</td></tr>';
}
async function gantt(seq=navSeq){renderGantt();}

function canManageLevel3(){
  return admin() || String(currentProfile?.department||'').toLowerCase()==='development';
}
let level3RowsCache=[];
async function loadLevel3Rows(){
  let r=await sb.from("portal_level3_documents").select("*").order("created_at",{ascending:false});
  if(r.error){
    // Table may not have been created yet; continue with the supplied controlled master.
    level3RowsCache=[...LEVEL3_WORK_INSTRUCTIONS];
    return {error:r.error};
  }
  const dbRows=(r.data||[]).map(x=>({
    id:x.id, format_no:x.format_no, title:x.title, issue_date:x.issue_date||'', revision:x.revision||'',
    purpose:x.purpose||'', scope:x.scope||'', owner:x.owner||'', procedure:x.procedure_steps||'',
    status:x.status||'Active', source:'portal', created_by:x.created_by
  }));
  level3RowsCache=[...dbRows,...LEVEL3_WORK_INSTRUCTIONS.filter(w=>!dbRows.some(d=>d.format_no===w.format_no))];
  return {error:null};
}
function renderLevel3(){
  $('main').innerHTML=`<div class="page-title"><div><h1>📚 Level 3 Documents</h1><p>Controlled Level 3 documentation • Development Department</p></div><div class="actions-inline">${canManageLevel3()?`<button class="btn btn-primary" onclick="newWorkInstruction()">＋ Create New Work Instruction</button>`:''}<a class="btn btn-secondary" href="documents/QAF-DEVP-L-01_Work_Instruction.xlsx" download>⬇ Master Excel</a><button class="btn btn-secondary" onclick="exportLevel3()">⬇ Export CSV</button></div></div>
  <div class="panel"><div class="subtabs"><button class="subtab active" id="l3_wi_tab" onclick="level3Tab('work_instructions')">📄 Work Instructions <span id="wi_total">${level3RowsCache.length}</span></button></div><div id="level3_content"></div></div>`;
  level3Tab('work_instructions');
}
