async function scanning(){
 const m='scanning_dwm'; if(!can(m,'view')) return $('main').innerHTML='<div class="alert alert-error">No access to 3D Scanning DWM & OEE.</div>';
 const today=new Date().toISOString().slice(0,10);
 let er=await sb.from('scanning_engineers').select('*').eq('active',true).order('engineer_name');
 let tr=await sb.from('scanning_tasks').select('*,scanning_engineers(engineer_name,employee_id)').eq('task_date',today).order('id',{ascending:false});
 let engineers=er.data||[], tasks=tr.data||[];
 if(tr.error) return $('main').innerHTML=`<div class="alert alert-error">${esc(tr.error.message)}</div>`;
 const done=tasks.filter(x=>String(x.work_status).toLowerCase()==='completed').length;
 const ok=tasks.filter(x=>String(x.work_status).toLowerCase()==='completed' && ['OK','APPROVED'].includes(String(x.final_result||'').toUpperCase())).length;
 const planned=tasks.reduce((a,x)=>a+(+x.planned_minutes||0),0), actual=tasks.reduce((a,x)=>a+(+x.actual_minutes||0),0), down=tasks.reduce((a,x)=>a+(+x.downtime_minutes||0),0);
 const av=planned?Math.max(0,Math.min(1,(planned-down)/planned))*100:0, pe=actual?Math.max(0,Math.min(1,planned/actual))*100:0, qu=done?ok/done*100:0, oee=av*pe*qu/10000;
 $('main').innerHTML=`<div class="page-title"><div><h1>3D Scanning DWM & OEE</h1><p>Two-shift daily work management • Engineer-wise task assignment • OEE-style KPI</p></div>${admin()?`<button class="btn btn-secondary" onclick="manageScanEngineers()">Manage Engineers</button>`:''}${can(m,'add')?`<button class="btn btn-primary" onclick="scanForm()">+ Assign Scanning Task</button>`:''}</div>
 <div class="stats stylish-stats"><div class="stat"><div class="icon">📋</div><div class="n">${tasks.length}</div><div class="l">Today's Tasks</div></div><div class="stat"><div class="icon">⏱️</div><div class="n">${av.toFixed(1)}%</div><div class="l">Availability</div></div><div class="stat"><div class="icon">⚡</div><div class="n">${pe.toFixed(1)}%</div><div class="l">Performance</div></div><div class="stat"><div class="icon">🎯</div><div class="n">${oee.toFixed(1)}%</div><div class="l">OEE</div></div></div>
 <div class="panel"><div class="searchbar advanced-searchbar"><input id="scan_q" placeholder="Quick search engineer, customer, part, task..." oninput="filterScan()"><button class="btn btn-secondary" onclick="openScanAdvancedFilter()">⚙ Advanced Filter</button><button class="btn btn-secondary" onclick="clearScanAdvancedFilter()">Clear Filters</button><button class="btn btn-secondary" onclick="exportScanning(false)">⬇ Export Current CSV</button><button class="btn btn-secondary" onclick="exportScanning(true)">⬇ Export All CSV</button></div><div id="scan_filter_summary" class="filter-summary"></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Shift</th><th>Plant</th><th>Engineer</th><th>Customer</th><th>Part</th><th>Work Type</th><th>Priority</th><th>Planned</th><th>Status</th><th>Result</th><th>Action</th></tr></thead><tbody id="scan_rows">${scanRows(tasks)}</tbody></table></div></div>`;
 window._scanTasks=tasks; window._scanEngineers=engineers;
}
function scanRows(tasks){return (tasks||[]).map(x=>`<tr><td>${esc(x.task_date)}</td><td><span class="badge ${x.shift_code==='A'?'active':'review'}">${esc(x.shift_code)}</span></td><td>${esc(x.plant_unit)}</td><td>${esc(x.scanning_engineers?.engineer_name||'Unassigned')}</td><td>${esc(x.customer_name)}</td><td>${esc(x.part_short_name)}</td><td>${esc(x.work_type)}</td><td>${esc(x.priority)}</td><td>${esc(x.planned_minutes)} min</td><td>${esc(x.work_status)}</td><td>${esc(x.final_result)}</td><td>${can('scanning_dwm','edit')?`<button class="btn btn-secondary" onclick="editScan(${x.id})">Edit</button>`:`<button class="btn btn-secondary" onclick="viewScan(${x.id})">View</button>`}${admin()?` <button class="btn btn-danger" onclick="deleteScan(${x.id})">Delete</button>`:''}</td></tr>`).join('')||'<tr><td colspan="12" class="empty">No tasks found.</td></tr>'}
const SCAN_FILTERS=[['task_date','Date'],['shift_code','Shift'],['plant_unit','Plant / Unit'],['customer_name','Customer'],['part_short_name','Part / Short Name'],['part_no','Part No.'],['priority','Priority'],['work_type','Work Type'],['work_status','Status'],['final_result','Final Result'],['report_no','Report No.']];
function openScanAdvancedFilter(){const st=window._scanAdvFilters||{};$('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal filter-modal"><div class="modal-header"><div><h2>3D Scanning Advanced Filter</h2><p class="small">Combine date, shift, plant, customer, engineer and task conditions.</p></div><button class="close" onclick="closeM()">×</button></div><div class="filter-grid">${SCAN_FILTERS.map(f=>filterInput(f,st[f[0]]||'')).join('')}<div class="form-group"><label>Scanning Engineer</label><input id="af_scan_engineer" value="${esc(st._engineer||'')}" placeholder="Engineer name"></div></div><div class="actions"><button class="btn btn-secondary" onclick="clearScanAdvancedFilter(true)">Clear</button><button class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary" onclick="applyScanAdvancedFilter()">Apply Filter</button></div></div></div>`)}
function collectScanFilters(){const o={};SCAN_FILTERS.forEach(f=>{const k=f[0];if(k==='task_date'){const from=$('af_task_date_from')?.value||'',to=$('af_task_date_to')?.value||'';if(from||to)o[k]={from,to}}else{const v=$('af_'+k)?.value?.trim()||'';if(v)o[k]=v}});const eng=$('af_scan_engineer')?.value?.trim()||'';if(eng)o._engineer=eng;return o}
function applyScanAdvancedFilter(){window._scanAdvFilters=collectScanFilters();closeM();filterScan()}
function clearScanAdvancedFilter(inside=false){window._scanAdvFilters={};if(inside)closeM();filterScan()}
function scanAdvMatch(x){const st=window._scanAdvFilters||{};return Object.entries(st).every(([k,v])=>{if(k==='_engineer')return String(x.scanning_engineers?.engineer_name||'').toLowerCase().includes(v.toLowerCase());if(typeof v==='object'){const d=x[k]?String(x[k]).slice(0,10):'';return (!v.from||d>=v.from)&&(!v.to||d<=v.to)}return String(x[k]??'').toLowerCase().includes(String(v).toLowerCase())})}
function filterScan(){let q=($('scan_q')?.value||'').toLowerCase(),a=(window._scanTasks||[]).filter(x=>scanAdvMatch(x)&&(!q||JSON.stringify(x).toLowerCase().includes(q)));$('scan_rows').innerHTML=scanRows(a);if($('scan_filter_summary'))$('scan_filter_summary').innerHTML=`<span class="small">${Object.keys(window._scanAdvFilters||{}).length?'<b>Advanced filters active.</b> ':''}${a.length} result${a.length===1?'':'s'}</span>`}
async function exportScanning(all){
  let rows=[];
  if(all){const r=await sb.from('scanning_tasks').select('*,scanning_engineers(engineer_name,employee_id)').order('task_date',{ascending:false});if(r.error)return alert(r.error.message);rows=r.data||[];}else{rows=(window._scanTasks||[]).filter(x=>scanAdvMatch(x)&&(!($('scan_q')?.value||'').trim()||JSON.stringify(x).toLowerCase().includes(($('scan_q').value||'').toLowerCase())))}
  rows=rows.map(x=>({...x,scanning_engineer:x.scanning_engineers?.engineer_name||'Unassigned',scanning_engineer_id:x.scanning_engineers?.employee_id||''}));
  const fields=[['task_no','Task No.'],['task_date','Date'],['shift_code','Shift'],['plant_unit','Plant'],['scanning_engineer','Engineer'],['scanning_engineer_id','Employee ID'],['customer_name','Customer'],['part_short_name','Part / Short Name'],['part_no','Part No.'],['material_type','Material Type'],['received_qty','Received Qty'],['unit','Unit'],['priority','Priority'],['work_type','Work Type'],['planned_minutes','Planned Minutes'],['actual_minutes','Actual Minutes'],['downtime_minutes','Downtime Minutes'],['work_status','Status'],['final_result','Result'],['report_no','Report No.'],['observation','Observation'],['remark','Remark']];downloadCSV(rows,fields,`Mutha_Scanning_DWM_OEE_${all?'All':'Filtered'}.csv`);
}

function applyScanHistory(index){const rows=window._scanFormHistory||[];const x=rows[Number(index)];if(!x)return;const map={task_date:'s_task_date',shift_code:'s_shift',plant_unit:'s_plant',assigned_engineer_id:'s_eng',customer_name:'s_customer_name',part_short_name:'s_part_short_name',part_no:'s_part_no',material_type:'s_material_type',cavity_note:'s_cavity_note',received_qty:'s_received_qty',unit:'s_unit',priority:'s_priority',work_type:'s_work_type',planned_minutes:'s_planned_minutes',work_details:'s_work_details',reason:'s_reason',work_status:'s_work_status',final_result:'s_final_result',report_no:'s_report_no',observation:'s_observation',remark:'s_remark'};Object.entries(map).forEach(([k,id])=>{const el=$(id);if(el)el.value=x[k]??''});if($('scan_history_note'))$('scan_history_note').textContent='Previous task loaded. You can edit any field before saving.'}
