async function scanForm(id){
 if(!can('scanning_dwm',id?'edit':'add'))return alert('No permission.');
 let x={task_date:new Date().toISOString().slice(0,10),shift_code:'A',plant_unit:'MFPL',priority:'Medium',work_status:'Assigned',planned_minutes:60};
 if(id){let r=await sb.from('scanning_tasks').select('*').eq('id',id).single();if(r.error)return alert(r.error.message);x=r.data}
 let er=await sb.from('scanning_engineers').select('*').eq('active',true).order('engineer_name');let engineers=er.data||[]; window._scanFormHistory=[]; if(!id){let hr=await sb.from('scanning_tasks').select('*').order('id',{ascending:false}).limit(50); if(!hr.error)window._scanFormHistory=hr.data||[];}
 $('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal"><div class="modal-header"><h2>${id?'Edit':'Assign'} Scanning Task</h2><button class="close" onclick="closeM()">×</button></div><div id="sfm"></div>${!id?`<div class="history-copy-box"><div class="form-group"><label>Previous Task / History</label><select id="scan_history" onchange="applyScanHistory(this.value)"><option value="">— Start with a blank new task —</option>${window._scanFormHistory.map((r,i)=>`<option value="${i}">${esc(scanHistoryLabel(r))}</option>`).join('')}</select><div id="scan_history_note" class="small">Select a previous task to copy its values. All fields remain editable.</div></div></div>`:''}<form onsubmit="saveScan(event,${id||0})"><div class="grid3">
 <div class="form-group"><label>Task Date</label><input id="s_task_date" type="date" value="${esc(x.task_date)}" required></div><div class="form-group"><label>Shift</label><select id="s_shift"><option ${x.shift_code==='A'?'selected':''}>A</option><option ${x.shift_code==='B'?'selected':''}>B</option></select></div><div class="form-group"><label>Plant / Unit</label><input id="s_plant" value="${esc(x.plant_unit||'')}" required></div>
 <div class="form-group"><label>Assigned Scanning Engineer</label><select id="s_eng"><option value="">Unassigned</option>${engineers.map(e=>`<option value="${e.id}" ${String(x.assigned_engineer_id)===String(e.id)?'selected':''}>${esc(e.engineer_name)} (${esc(e.employee_id||'')})</option>`).join('')}</select></div>
 ${[['customer_name','Customer'],['part_short_name','Part / Short Name'],['part_no','Part No.'],['material_type','Material Type'],['cavity_note','Cavity / Qty Note'],['received_qty','Received Qty'],['unit','Unit'],['priority','Priority'],['work_type','Work Type'],['planned_minutes','Planned Minutes'],['work_details','Work Details'],['reason','Reason']].map(f=>`<div class="form-group"><label>${f[0]==='priority'?'Priority':f[1]}</label>${f[0]==='priority'?`<select id="s_${f[0]}">${['Low','Medium','High'].map(v=>`<option ${x[f[0]]===v?'selected':''}>${v}</option>`).join('')}</select>`:`<input id="s_${f[0]}" value="${esc(x[f[0]]||'')}">`}</div>`).join('')}
 <div class="form-group"><label>Status</label><select id="s_work_status">${['Assigned','In Progress','On Hold','Completed','Cancelled'].map(v=>`<option ${x.work_status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-group"><label>Final Result</label><select id="s_final_result"><option value="">-</option>${['OK','NG','Approved','Rejected'].map(v=>`<option ${x.final_result===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-group"><label>Report No.</label><input id="s_report_no" value="${esc(x.report_no||'')}"></div>
 <div class="form-group full"><label>Observation / Abnormality</label><textarea id="s_observation">${esc(x.observation||'')}</textarea></div><div class="form-group full"><label>Remarks</label><textarea id="s_remark">${esc(x.remark||'')}</textarea></div>
 </div><div class="actions"><button type="button" class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary">Save Task</button></div></form></div></div>`)
}
async function saveScan(e,id){e.preventDefault();let o={task_date:$('s_task_date').value,shift_code:$('s_shift').value,plant_unit:$('s_plant').value,assigned_engineer_id:$('s_eng').value||null,customer_name:$('s_customer_name').value,part_short_name:$('s_part_short_name').value,part_no:$('s_part_no').value,material_type:$('s_material_type').value,cavity_note:$('s_cavity_note').value,received_qty:+$('s_received_qty').value||null,unit:$('s_unit').value,priority:$('s_priority').value,work_type:$('s_work_type').value,planned_minutes:+$('s_planned_minutes').value||0,work_details:$('s_work_details').value,reason:$('s_reason').value,work_status:$('s_work_status').value,final_result:$('s_final_result').value,report_no:$('s_report_no').value,observation:$('s_observation').value,remark:$('s_remark').value,updated_by:currentUser.id};let r=id?await sb.from('scanning_tasks').update(o).eq('id',id).select().single():await sb.from('scanning_tasks').insert({...o,created_by:currentUser.id,assigned_by:currentUser.id}).select().single();if(r.error)return err('sfm',r.error.message);closeM();scanning()}
async function deleteScan(id){if(!admin())return alert('Only Admin can delete scanning tasks.');if(!confirm('Delete this scanning task? This action cannot be undone.'))return;const r=await sb.from('scanning_tasks').delete().eq('id',id);if(r.error)return alert(r.error.message);scanning()}
function editScan(id){scanForm(id)}
function viewScan(id){let x=(window._scanTasks||[]).find(v=>v.id===id);if(!x)return;alert(`Task ${x.task_no||x.id}\nEngineer: ${x.scanning_engineers?.engineer_name||'Unassigned'}\nStatus: ${x.work_status}\nResult: ${x.final_result||'-'}`)}

async function manageScanEngineers(){
 if(!admin())return;
 let u=await sb.from('user_profiles').select('id,employee_id,employee_name,department,designation,plant_unit').eq('approval_status','Approved').order('employee_name');
 if(u.error)return alert(u.error.message);
 let e=await sb.from('scanning_engineers').select('*'); if(e.error)return alert(e.error.message);
 const existing=Object.fromEntries((e.data||[]).map(x=>[x.user_id,x]));
 window._scanEngineerIds=(u.data||[]).map(x=>x.id); $('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal"><div class="modal-header"><h2>Scanning Engineer Master</h2><button class="close" onclick="closeM()">×</button></div><div class="tablewrap"><table><thead><tr><th>Use</th><th>Engineer</th><th>Employee ID</th><th>Plant</th><th>Default Shift</th></tr></thead><tbody>${(u.data||[]).map(x=>{let z=existing[x.id]||{};return `<tr><td><input type="checkbox" id="se_use_${x.id}" ${z.active?'checked':''}></td><td>${esc(x.employee_name)}<br><small>${esc(x.designation||'')}</small></td><td>${esc(x.employee_id||'')}</td><td><input id="se_plant_${x.id}" value="${esc(z.plant_unit||x.plant_unit||'')}"></td><td><select id="se_shift_${x.id}"><option ${z.default_shift==='A'?'selected':''}>A</option><option ${z.default_shift==='B'?'selected':''}>B</option></select></td></tr>`}).join('')}</tbody></table></div><div class="actions"><button class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary" onclick="saveScanEngineers()">Save Engineers</button></div></div></div>`)
}
async function saveScanEngineers(){
 for(const id of (window._scanEngineerIds||[])){const use=$(`se_use_${id}`)?.checked;const user=(await sb.from('user_profiles').select('employee_id,employee_name,plant_unit').eq('id',id).single()).data||{};let r=await sb.from('scanning_engineers').upsert({user_id:id,employee_id:user.employee_id,engineer_name:user.employee_name,plant_unit:$(`se_plant_${id}`).value,default_shift:$(`se_shift_${id}`).value,active:use},{onConflict:'user_id'});if(r.error)return alert(r.error.message)}
 alert('Scanning engineer master saved.');closeM();scanning();
}
